<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useTripWeather } from '../../shared/useTripWeather';
import PickupCode from './PickupCode.vue';
import WebScanner from './WebScanner.vue';

import { api } from '../api';
import PhotoField from './PhotoField.vue';
import PhotoGrid from './PhotoGrid.vue';
import { useLife } from '../../shared/useLife';
import { lifeTypes, lifeStates, calendarFile } from '../../shared/life';
import { type Row, formatTime } from '../../shared/domain';
const props=defineProps<{user:Row|null;target?:Row|null}>();
const emit=defineEmits<{(event:'clear-target'):void;(event:'join'):void;(event:'navigate',page:string):void;(event:'contact',member:Row):void}>();
const {unavailableApplications,showFinished,taskRows,type,tab,rows,selected,editing,form,options,query,region,employment,error,message,loading,busy,photoBusy,photos,applications,checked,meeting,inbox,mine,feedback,reservations,orders,signups,note,applicationText,orderId,slotId,credential,pickupCode,pickupCheck,actionPrompt,approved,staff,admin,currentType,fields,canCreate,filtered,actions,unread,canEdit,canApply,load,open,back,switchTab,switchType,edit,keepDraft,restoreDraft,clearDraft,save,confirmAction,entryAction,appAction,apply,subscribe,toggleCheck,report,replyFeedback,readMessage,selectMeeting,reserve,cancelPickup,getCredential,checkPickup}=useLife(()=>props.user,api,{get:k=>localStorage.getItem(k)||'',set:(k,v)=>localStorage.setItem(k,v),remove:k=>localStorage.removeItem(k)});
watch(()=>props.target, target=>{if(!target)return;if(target.lifeTab)switchTab(target.lifeTab);else void open(target.targetId||target.id);emit('clear-target');},{immediate:true});
const tripWeather=useTripWeather(()=>selected.value,()=>props.user,api);
const scanning=ref(false);
function scanned(value:string){const match=/^SYH:PICKUP:([0-9a-f-]{72})$/i.exec(value.trim());if(!match){error.value='这不是有效的沭阳之家取货凭证';return;}pickupCode.value=match[1];pickupCheck.value=null;scanning.value=false;}
function scan(){scanning.value=!scanning.value;}
const large=ref(false);
const pictures=computed(()=>(selected.value?.photos||[]).map((id:string)=>({id,name:'服务事项照片'})));
const pickupOrders=computed(()=>orders.value.filter(o=>o.delivery==='pickup'&&['confirmed','ready'].includes(o.status)));
const slots=computed(()=>rows.value.filter(r=>r.type==='slot'&&r.status==='open'&&new Date(r.startsAt).getTime()>Date.now()));
function fieldOptions(field:Row):Row[]{return field.source?options.value[field.source]||[]:(field.options||[]).map((v:string)=>({id:v,title:v}));}
async function copy(value:string){try{await navigator.clipboard.writeText(value);message.value='已复制';}catch{error.value='复制失败，请选择文字手动复制';}}
function calendar(event:Row){const url=URL.createObjectURL(new Blob([calendarFile(event)],{type:'text/calendar;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='沭阳之家活动.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function source(url:string){window.open(url,'_blank','noopener,noreferrer');}
function contact(id:string,name:string){emit('contact',{id,name});}
</script>
<template>
  <section class="life-hub" :class="{'life-large':large}">
    <header class="life-hero"><div><div class="life-eyebrow">沭阳之家 · 生活服务</div><h2 class="life-h2">生活服务</h2><p>办事有清单，求助有回应，进度看得见。</p></div><button class="life-font" :aria-pressed="large" @click="large=!large">{{large?'标准字号':'大字模式'}}</button></header>
    <div v-if="error" class="life-alert" role="alert">{{error}}<button v-if="!selected&&!editing" :disabled="loading||busy" @click="load">重新加载</button></div><div v-if="message" class="life-success" role="status">{{message}}</div>
    <nav class="life-tabs" aria-label="服务范围"><button :disabled="busy" :class="{active:['public','mine','manage'].includes(tab)}" @click="switchTab('public')">服务广场</button><button v-if="approved" :disabled="busy" :class="{active:tab==='tasks'}" @click="switchTab('tasks')">服务事项</button><button v-if="approved" :disabled="busy" :class="{active:tab==='inbox'}" @click="switchTab('inbox')">服务通知 {{unread||''}}</button><button v-if="approved" :disabled="busy" :class="{active:tab==='pickup'}" @click="switchTab('pickup')">我的自提</button><button v-if="approved" :disabled="busy" :class="{active:tab==='feedback'}" @click="switchTab('feedback')">纠错反馈</button></nav>
    <div v-if="loading" class="life-muted" role="status">正在加载最新进展…</div>
    <section v-if="actionPrompt" class="life-card life-confirm"><h3 class="life-h3">{{actionPrompt.label}}</h3><label class="life-field"><span>处理说明</span><textarea v-model="note" maxlength="1000" placeholder="说明原因或处理结果，至少2字"/></label><div class="life-actions"><button class="primary" :disabled="busy" @click="confirmAction">确认操作</button><button class="outline" :disabled="busy" @click="actionPrompt=null">取消</button></div></section>
    <template v-if="editing">
      <div class="life-heading"><h3 class="life-h3">{{form.id?'编辑':'发布'}}{{currentType.name}}</h3><button class="outline" :disabled="busy||photoBusy" @click="back">返回</button></div>
      <form class="life-card life-form" @submit.prevent="save">
        <p class="life-muted">{{type==='service'?'服务名片需自愿开启名录公开。自填技能与报价不代表平台资质认证。':type==='lost'?'请遮挡证件号码，保留一项物品特征用于私下核验。':'内容审核通过后展示。请填写真实信息，及时维护有效期。'}}</p>
        <div class="life-form-grid"><label v-for="field in fields" :key="field.key" class="life-field" :class="{'life-wide':field.kind==='textarea'}"><span>{{field.label}}{{field.optional?'（选填）':' *'}}</span>
          <select v-if="field.options||field.source" v-model="form[field.key]" :required="!field.optional"><option value="" disabled>请选择</option><option v-for="item in fieldOptions(field)" :key="item.id" :value="item.id">{{item.title}}</option></select>
          <textarea v-else-if="field.kind==='textarea'" v-model="form[field.key]" :maxlength="field.max||4000" :placeholder="field.hint||''" :required="!field.optional"/>
          <input v-else v-model="form[field.key]" :type="field.kind==='datetime'?'datetime-local':field.kind==='date'?'date':field.kind==='number'?'number':'text'" :maxlength="field.max||500" :placeholder="field.hint||''" :required="!field.optional" :min="field.kind==='number'?1:undefined">
        </label></div>
        <label v-if="form.id" class="life-field"><span>本次修改说明</span><input v-model="form.changeNote" maxlength="300" placeholder="方便订阅者了解发生了什么变化"></label>
        <div v-if="form.photos?.length" class="life-actions"><button v-for="(id,index) in form.photos" :key="id" type="button" class="outline" @click="form.photos.splice(index,1)">移除原照片 {{index+1}}</button></div>
        <PhotoField v-if="6-(form.photos?.length||0)>0" :key="String(form.id||form.requestId)" v-model="photos" :user-id="user?.id" scope="life" :max="6-(form.photos?.length||0)" :disabled="busy" @busy="photoBusy=$event"/>
        <div class="life-actions"><button class="primary" :disabled="busy||photoBusy">{{busy?'正在保存…':'提交保存'}}</button><button type="button" class="outline" :disabled="busy" @click="keepDraft">保存文字草稿</button><button type="button" class="text-button" :disabled="busy" @click="restoreDraft">恢复草稿</button><button type="button" class="text-button" :disabled="busy" @click="clearDraft">清除草稿</button></div>
      </form>
    </template>
    <template v-else-if="selected">
      <button class="text-button life-back" :disabled="busy" @click="back">← 返回列表</button>
      <article class="life-card life-detail"><div class="life-kicker">{{selected.category}} · {{selected.region}}</div><h3 class="life-h3">{{selected.title}}</h3><div class="life-meta"><span class="life-badge">{{selected.expired?'已过期':lifeStates[selected.status]}}</span><span>{{selected.ownerName}} · 更新于 {{formatTime(selected.updatedAt)}}</span></div><p class="life-prose">{{selected.content}}</p>
        <p v-if="selected.reviewNote" class="life-alert">审核说明：{{selected.reviewNote}}</p><p v-if="selected.deadline" class="life-muted">有效至 {{selected.deadline}}</p>
        <div v-if="selected.type==='job'" class="life-facts"><p>用工单位：{{selected.employer}} · {{selected.publisher}}</p><p>薪资：{{selected.salary}} · {{selected.employment}}</p><p>时间：{{selected.schedule}}</p><p>{{selected.benefits}}</p><p class="life-muted">发布信息审核不等于企业资质认证。</p></div>
        <div v-if="selected.type==='service'" class="life-facts"><p>联系时段：{{selected.availability}}</p><p>服务与收费：{{selected.pricing}}</p></div>
        <p v-if="selected.type==='help'" class="life-muted">帮助方式：{{selected.method}}；处理结果由求助者本人确认。</p><p v-if="selected.type==='lost'" class="life-muted">{{selected.lostType}} · {{selected.occurredOn}}；认领说明仅相关双方与授权管理员可见。</p>
        <PhotoGrid :key="selected.id+':'+user?.id" :photos="pictures"/>
        <section v-if="selected.type==='guide'" class="life-inset"><h4 class="life-h4">我的材料清单</h4><p class="life-muted">仅记录个人准备进度，不代表官方办理结果。</p><button v-for="item in selected.checklist" :key="item" class="life-check" :aria-pressed="checked.includes(item)" :disabled="busy||!approved" @click="toggleCheck(item)"><span>{{checked.includes(item)?'✓':'○'}}</span>{{item}}</button><p>{{checked.length}} / {{selected.checklist.length}} 项已准备</p><p :class="selected.stale?'life-alert':'life-muted'">{{selected.stale?'内容超过90天未核验，请以官方最新说明为准。':'最近核验：'+selected.verifiedOn}}</p><button class="outline" @click="source(selected.sourceUrl)">查看来源：{{selected.sourceName}} ↗</button></section>
        <section v-if="selected.type==='trip'" class="life-inset"><h4 class="life-h4">出发前看这里</h4><p>{{selected.event.title}} · {{formatTime(selected.event.startsAt)}}</p><p>活动地点：{{selected.event.location}}</p><p class="life-prose">{{selected.meeting}}</p><p class="life-prose">{{selected.transport}}</p><p>组织者：{{selected.contact}}</p><div class="life-actions"><button class="outline" @click="calendar(selected.event)">保存到日历</button><button class="outline" @click="emit('navigate','events')">活动报名与详情</button><button v-if="selected.event.status==='published'" class="outline" @click="emit('navigate','checkin')">到场签到</button></div><p v-if="selected.event.status!=='published'" class="life-alert">活动已取消或撤下，请以活动详情最新安排为准。</p><p class="life-muted">{{tripWeather}}</p><h4 class="life-h4">选择集合点</h4><p class="life-muted">需先报名，集合点选择不代表签到成功。</p><div class="life-actions"><button v-for="point in selected.meetingPoints" :key="point" :disabled="busy||!approved" :class="meeting.mine?.point===point?'primary':'outline'" @click="selectMeeting(point)">{{point}} · {{meeting.counts?.[point]||0}} 人</button><button v-if="meeting.mine?.point" class="text-button" :disabled="busy" @click="selectMeeting('')">取消集合点</button></div><div v-if="staff&&meeting.participants?.length"><p v-for="person in meeting.participants" :key="person.id">{{person.userName}} · {{person.point}}</p></div></section>
        <section v-if="selected.type==='arrival'" class="life-inset"><h4 class="life-h4">{{selected.product.title}}</h4><p>预计到货：{{selected.expectedOn}} · 当前库存 {{selected.product.stock}}</p><p class="life-muted">到货预告不生成订单或锁定库存。</p><button class="outline" @click="emit('navigate','shop')">查看商品与下单</button></section>
        <section v-if="selected.type==='progress'" class="life-inset"><h4 class="life-h4">{{selected.project.title}}</h4><p>{{selected.milestone}} · 计划日期 {{selected.plannedOn}}</p><p>{{selected.project.type}}目标 {{selected.project.goal}} {{selected.project.unit}} · 有效认领 {{selected.project.pledged}} {{selected.project.unit}}</p><p v-if="selected.project.type==='资金意向'" class="life-alert">资金仅登记意向，未在线收款。</p><p v-else>已核实交付 {{selected.project.delivered}} {{selected.project.unit}}</p><button class="outline" @click="emit('navigate','crowdfunding')">查看项目与认领</button></section>
        <section v-if="selected.type==='slot'" class="life-inset"><p>{{formatTime(selected.startsAt)}} — {{formatTime(selected.endsAt)}}</p><p>接待数量：{{selected.capacity}} 单</p><button class="primary" :disabled="!approved" @click="switchTab('pickup')">选择订单预约</button></section>
        <div class="life-actions"><button v-if="approved" class="outline" :disabled="busy" @click="subscribe">{{selected.subscribed?'取消更新提醒':'订阅站内更新'}}</button><button v-if="approved" class="text-button" :disabled="busy" @click="report">信息纠错</button><button v-if="canEdit" class="outline" :disabled="busy" @click="type=selected.type;edit(selected)">编辑内容</button><button v-for="action in actions" :key="action.id" class="outline" :disabled="busy" @click="entryAction(action.id,action.label)">{{action.label}}</button></div>
        <div v-if="selected.history?.length" class="life-history"><h4 class="life-h4">处理记录</h4><p v-for="(item,index) in selected.history" :key="index">{{formatTime(item.time)}} · {{item.actor}}：{{item.note||'内容更新'}}</p></div>
      </article>
      <section v-if="canApply" class="life-card"><h3 class="life-h3">{{selected.type==='job'?'表达求职意向':selected.type==='lost'?'提交认领／线索':selected.type==='service'?'咨询这项服务':'申请帮忙'}}</h3><label class="life-field"><span>说明（5–1000字）</span><textarea v-model="applicationText" maxlength="1000" placeholder="介绍情况；认领物品时填写未公开的特征，请勿填写证件号码"/></label><button class="primary" :disabled="busy" @click="apply">提交申请</button></section>
      <section v-if="applications.length" class="life-card"><h3 class="life-h3">{{selected.mine?'收到的申请':'我的申请'}}</h3><article v-for="app in applications" :key="app.id" class="life-application"><div class="life-meta"><b>{{app.userName}}</b><span class="life-badge">{{lifeStates[app.status]}}</span></div><p class="life-prose">{{app.message}}</p><p v-if="app.note" class="life-prose">处理说明：{{app.note}}</p><p v-if="app.releaseRequested" class="life-alert">负责人申请退出，等待求助者确认。</p><div class="life-actions"><template v-if="selected.mine&&app.status==='submitted'"><button class="primary" :disabled="busy" @click="appAction(app,'accept','接受申请')">接受申请</button><button class="outline" :disabled="busy" @click="appAction(app,'reject','暂不合适')">暂不合适</button></template><button v-if="app.userId===user?.id&&(app.status==='submitted'||['job','service'].includes(selected.type)&&app.status==='accepted')" class="outline" :disabled="busy" @click="appAction(app,'withdraw','撤回申请')">撤回</button><template v-if="app.userId===user?.id&&app.status==='accepted'&&selected.type==='help'&&selected.status==='working'"><button class="primary" :disabled="busy" @click="appAction(app,'outcome','提交处理结果')">提交处理结果</button><button class="outline" :disabled="busy" @click="appAction(app,'request-release','申请退出帮办')">申请退出</button></template><button v-if="app.status==='accepted'" class="outline" @click="contact(selected.mine?app.userId:selected.ownerId,selected.mine?app.userName:selected.ownerName)">申请私聊沟通</button></div></article></section>
    </template>
    <template v-else>
      <template v-if="['public','mine','manage'].includes(tab)"><div class="life-categories"><button v-for="item in lifeTypes" :key="item.id" :disabled="busy" :class="{active:type===item.id}" @click="switchType(item.id)"><span>{{item.mark}}</span>{{item.name}}</button></div><div class="life-heading"><div><h3 class="life-h3">{{currentType.name}}</h3><p class="life-muted">{{currentType.intro}}</p></div><button v-if="canCreate" class="primary" @click="edit()">＋ 发布</button></div><div class="life-actions"><button class="outline" :class="{selected:tab==='public'}" @click="switchTab('public')">公开信息</button><button v-if="approved" class="outline" :class="{selected:tab==='mine'}" @click="switchTab('mine')">我的发布</button><button v-if="staff" class="outline" :class="{selected:tab==='manage'}" @click="switchTab('manage')">审核与维护</button></div><div class="life-filters"><input v-model="query" aria-label="搜索服务" placeholder="搜索标题、分类或内容" maxlength="80"><input v-model="region" aria-label="筛选地区" placeholder="城市／区县" maxlength="80"><select v-if="type==='job'" v-model="employment" aria-label="用工类型"><option v-for="item in ['全部','全职','兼职','临时','实习']" :key="item">{{item}}</option></select></div><div class="life-grid"><button v-for="row in filtered" :key="row.id" class="life-card life-list-item" @click="open(row.id)"><div class="life-meta"><span class="life-kicker">{{row.category}}</span><span class="life-badge">{{row.expired?'已过期':lifeStates[row.status]}}</span></div><h4 class="life-h4">{{row.title}}</h4><p>{{row.region}}<span v-if="row.salary"> · {{row.salary}}</span></p><p class="life-excerpt">{{row.content}}</p><div class="life-card-footer">{{row.ownerName}}<span>查看详情 →</span></div></button></div><div v-if="!loading&&!error&&!filtered.length" class="life-empty">{{query||region||employment!=='全部'?'没有匹配的信息，试试其他关键词。':'这里还没有信息，欢迎发布第一条真实内容。'}}</div></template>
      <template v-if="tab==='tasks'"><section v-if="unavailableApplications.length" class="life-card"><h3 class="life-h3">内容暂不可用的申请</h3><p class="life-muted">发布者修改的内容正在审核或已撤下，你仍可撤回此前提交的申请。</p><div v-for="app in unavailableApplications" :key="app.id"><p>{{app.message}}</p><button class="outline" :disabled="busy" @click="appAction(app,'withdraw','撤回申请')">撤回申请</button></div></section><div class="life-heading"><h3 class="life-h3">我参与的生活服务</h3><button class="outline" :aria-pressed="showFinished" @click="showFinished=!showFinished">{{showFinished?'仅进行中':'查看已结束'}}</button><button class="text-button" @click="load">刷新</button></div><div class="life-grid"><button v-for="row in taskRows" :key="row.id" class="life-card life-list-item" :disabled="row.status==='unavailable'" @click="open(row.id)"><span class="life-badge">{{lifeStates[row.status]}}</span><h4 class="life-h4">{{row.title}}</h4><p>查看进度与下一步 →</p></button></div><p v-if="!loading&&!taskRows.length" class="life-empty">保存清单、提交申请后，在这里继续办理。</p></template>
      <template v-if="tab==='inbox'"><div class="life-heading"><h3 class="life-h3">业务通知</h3><button class="outline" :disabled="busy||!unread" @click="readMessage()">全部已读</button></div><p class="life-muted">已读不代表事项完成。通知仅在站内展示。</p><button v-for="row in inbox" :key="row.id" class="life-card life-notification" @click="readMessage(row);row.targetPage && row.targetPage!=='life' && emit('navigate',row.targetPage)"><span class="life-badge">{{row.read?'已读':'未读'}}</span><p>{{row.message}}</p><span class="life-muted">{{formatTime(row.createdAt)}}</span></button><p v-if="!loading&&!inbox.length" class="life-empty">暂时没有新的业务通知。</p></template>
      <template v-if="tab==='feedback'"><h3 class="life-h3">纠错反馈与处理结果</h3><article v-for="row in feedback" :key="row.id" class="life-card"><span class="life-badge">{{lifeStates[row.status]}}</span><p class="life-prose">{{row.message}}</p><p v-if="row.reply">处理结果：{{row.reply}}</p><div class="life-actions"><button class="outline" @click="open(row.entryId)">查看原事项</button><button v-if="admin&&row.status==='pending'" class="primary" @click="replyFeedback(row)">处理反馈</button></div></article><p v-if="!loading&&!feedback.length" class="life-empty">在详情页点击“信息纠错”，可在这里查看处理结果。</p></template>
      <template v-if="tab==='pickup'"><section class="life-card"><h3 class="life-h3">预约取货时间</h3><p class="life-muted">选择已确认的自提订单。改约会释放旧时段，并使旧凭证失效。</p><label class="life-field"><span>自提订单</span><select v-model="orderId"><option value="">请选择订单</option><option v-for="order in pickupOrders" :key="order.id" :value="order.id">{{order.title}} × {{order.quantity}} · {{order.orderNo}}</option></select></label><label class="life-field"><span>取货时段</span><select v-model="slotId"><option value="">请选择时段</option><option v-for="slot in slots" :key="slot.id" :value="slot.id">{{slot.region}} · {{formatTime(slot.startsAt)}} — {{formatTime(slot.endsAt)}}</option></select></label><button class="primary" :disabled="busy||!orderId||!slotId" @click="reserve">确认预约／改约</button></section><article v-for="row in reservations" :key="row.id" class="life-card"><span class="life-badge">{{row.active?'已预约':row.status==='collected'?'已交付':'预约已失效'}}</span><h3 class="life-h3">{{row.order.title}} × {{row.order.quantity}}</h3><p>{{row.slot.region}} · {{formatTime(row.slot.startsAt)}} — {{formatTime(row.slot.endsAt)}}</p><p class="life-prose">{{row.slot.content}}</p><div v-if="row.active" class="life-actions"><button class="primary" :disabled="busy||row.order.status!=='ready'" @click="getCredential(row)">生成取货凭证</button><button class="outline" :disabled="busy||row.order.status!=='ready'" @click="getCredential(row,true)">生成限时代领凭证</button><button class="text-button" :disabled="busy" @click="getCredential(row,true,true)">撤销代领凭证</button><button class="text-button" :disabled="busy" @click="cancelPickup(row)">取消预约</button></div><p v-if="row.active&&row.order.status!=='ready'" class="life-muted">管理员备妥商品后可生成凭证。</p></article><section v-if="credential" class="life-card"><h3 class="life-h3">{{credential.delegate?'代领取货凭证':'本人取货凭证'}}</h3><PickupCode :code="credential.code"/><p class="life-code">{{credential.code}}</p><p>有效至 {{formatTime(credential.expiresAt)}}</p><button class="outline" @click="copy(credential.code)">复制凭证</button></section><section v-if="admin" class="life-card"><h3 class="life-h3">管理员核验取货</h3><button class="outline" :disabled="busy" @click="scan">扫码／图片识别取货码</button><WebScanner v-if="scanning" confirm-label="使用此取货凭证" @result="scanned"/><label class="life-field"><span>取货凭证</span><input v-model="pickupCode" maxlength="72" placeholder="粘贴买家提供的取货凭证" @input="pickupCheck=null"></label><button class="outline" :disabled="busy||!pickupCode" @click="checkPickup()">核对订单</button><div v-if="pickupCheck"><p>{{pickupCheck.order.title}} × {{pickupCheck.order.quantity}} · {{pickupCheck.order.orderNo}}</p><p>线下结算：{{pickupCheck.order.settlement==='confirmed'?'已核实':'待核实'}}；交付不会自动记为付款。</p><button class="primary" :disabled="busy||pickupCheck.collected" @click="checkPickup(true)">{{pickupCheck.collected?'已交付':'确认已交付商品'}}</button></div></section></template>
    </template>
    <section v-if="!approved" class="life-join"><p>登录并完成入会审核，即可保存清单、申请帮忙和接收进展。</p><button class="primary" @click="emit('join')">{{user?'查看入会进度':'登录／申请入会'}}</button></section>
  </section>
</template>
<style src="../../shared/life.css"></style>
